function loadImage(i){
 if(!Number.isInteger(i)||i<0||i>=data.images.length)return;
 if(i!==idx&&pending()){toast('请先应用、确认或取消当前预览，再换图片');return}
 idx=i;loadToken++;line=edit=first=preview=drag=null;photoMode=false;$('#photoMode').classList.remove('selected');let c=cur(),d=draft();$('#name').textContent=c.image_code;$('#question').textContent=c.question||'';$('#note').value=d.note;$('#topPending').checked=d.top_boundary_pending;$('#person').value='';populatePeople();$('#yaw').value=0;$('#axisAngle').value=String(d.axis_angle||0);$('#showHistoricalGT').checked=false;$('#orthogonal').checked=!c.non_orthogonal;$('#nonOrthogonalNotice').hidden=!c.non_orthogonal;
 $('#photoSource').textContent=c.photo?`真实原始全景 · 展示 ${c.display_dimensions?.join('×')||'2:1'} · 标注坐标仍为 1024×512`:'没有原始全景，禁止范围编辑。';
 const at=visible().findIndex(x=>x.i===idx);if(at>=0)navPage=Math.floor(at/20);fit();setMode('cut');renderEvidence();
 if(c.photo&&!photoImages[c.image_code]){let im=new Image();im.onload=()=>{if(cur()===c){renderPhoto();setEditAvailability()}};im.onerror=()=>{c.photo_error=true;if(cur()===c){render();toast('原图载入失败，暂不可编辑；请刷新后重试')}};im.src=c.photo;photoImages[c.image_code]=im}
 render();save();if(!c.details_loaded)loadDetails(c);
}
const svg=$('#bev');svg.onpointerdown=e=>{if(!canEdit())return;if(e.button!==0)return;e.preventDefault();let p=snap(world(e));let edge=e.target.dataset.edge,handle=e.target.dataset.handle;if(edge!==undefined&&mode==='edge'){drag={edge:+edge,start:p,moved:false};line=edit=first=preview=null;}else if(mode==='edge'){toast('拖动边中间的橙色方块来补空间');return}else if(handle!==undefined&&line){drag={handle:+handle,start:p,moved:false};}else{drag={start:p,moved:false,second:!!first};}svg.setPointerCapture(e.pointerId)};
svg.onpointermove=e=>{if(!drag)return;let p=snap(world(e));if(Math.hypot(p[0]-drag.start[0],p[1]-drag.start[1])>view.s/zoom*5)drag.moved=true;if(drag.edge!==undefined){let a=draft().polygon[drag.edge],b=draft().polygon[(drag.edge+1)%draft().polygon.length],len=Math.hypot(b[0]-a[0],b[1]-a[1]);edit={type:'edge_move',index:drag.edge,offset:((p[0]-drag.start[0])*(-(b[1]-a[1]))+(p[1]-drag.start[1])*(b[0]-a[0]))/len};compute();render()}else if(drag.handle!==undefined){if($('#orthogonal').checked){let other=line[drag.handle?'a':'b'];p=G.orthEnd(other,p,angle())}line[drag.handle?'b':'a']=p;compute();render()}else if(drag.moved){let a=first||drag.start;if(mode==='rectangle'){line=null;edit={type:'rectangle',a,b:p,angle:angle()}}else{edit=null;if($('#orthogonal').checked)p=G.orthEnd(a,p,angle());line={a,b:p,side:G.cross(a,p,[0,0])<0?-1:1}}compute();render()}};
svg.onpointerup=e=>{if(!drag)return;let d=drag,p=snap(world(e));drag=null;if(d.edge!==undefined||d.handle!==undefined){compute();render();return}if(d.moved){first=null;compute();render();return}if(first){if(mode==='rectangle')setRectangle(first,p);else setLine(first,p)}else{first=p;line=edit=preview=null;render()}};svg.onpointercancel=()=>{drag=null;clearLine()};
