function exportData(){return {schema:'manual_scope_crop_review_v2',editor_version:'3.0',source_commit:data.source_commit,exported_at:new Date().toISOString(),coordinate_frame:'camera_height_normalized_xz; original ERP 1024x512',GT_modified:false,legacy_field_notice:'original_GT_points_1024x512 and original_GT_floor_xz_h mean the unchanged editing baseline in this legacy schema, not necessarily the historical original dataset GT; use editing_reference_* and historical_original_GT_* for explicit versions.',unrecovered_drafts:clone(unrecoveredDrafts),records:data.images.map(c=>{let d=drafts[c.image_code];if(!d||!c.reference_points_1024x512?.length)return null;return {image_code:c.image_code,image_id:c.image_id,reference_object_id:c.reference_object_id,original_GT_points_1024x512:c.reference_points_1024x512,original_GT_floor_xz_h:G.floor(c.reference_points_1024x512||[]),...clone(d),floor_region_confirmed:status(c)==='confirmed',confirmed_version:confirmations[c.image_code]?clone(confirmations[c.image_code]):null,received_confirmed_version:c.confirmed_review?clone(c.confirmed_review):null,cropped_floor_xz_h:clone(d.polygon),manual_region_may_extend_GT:true,reference_ready:false,review_scope:'floor_region_only; top boundary must be separately validated',reference_version:c.reference_version,editing_reference_version:c.reference_version,editing_reference_object_id:c.reference_object_id,editing_reference_points_1024x512:clone(c.reference_points_1024x512),historical_original_GT_object_id:c.original_reference_object_id||null,historical_original_GT_points_1024x512:c.original_reference_points_1024x512?clone(c.original_reference_points_1024x512):c.reference_version==='original'?clone(c.reference_points_1024x512):null,evidence_source_commit:data.evidence_source_commit,formal_eligibility_changed:false}}).filter(Boolean)}}
